@app.cell
def _(ROOT, controller, hf_token_set):
    # ---- the runner used by the two run cells; defining it does nothing ----
    import time as _time
    from pathlib import Path as _P

    def run(mode):
        """Launch (or re-attach to) the worker and stream its log until it exits."""
        from qspec_hybrid.lineage import active_root

        root = active_root(ROOT)
        log = root / "worker.log"
        position = log.stat().st_size if log.exists() else 0

        if not hf_token_set:
            print(
                "[no HF token configured -- if the checkpoint or datasets are gated this\n"
                " worker will stop at download. Paste one in the HF token cell and re-run.]\n"
            )
        job = controller.read_json(root / "job.json", {})
        if controller.alive(job) and job.get("mode") != mode:
            print(
                f"[another notebook's worker ('{job.get('mode')}') is running in this workspace.\n"
                " Only one model fits on the GPU at a time. Let it finish (or stop it), then re-run this cell.]"
            )
            return controller.read_json(root / "status.json", {})
        if controller.alive(job):
            print(f"[re-attaching to running '{job.get('mode')}' worker, pid {job['pid']}]\n")
        else:
            job = controller.launch(root, mode)
            print(f"[started '{mode}', pid {job['pid']}]\n")

        def drain():
            nonlocal position
            if not log.exists():
                return
            with log.open("rb") as stream:
                stream.seek(position)
                chunk = stream.read()
            position += len(chunk)
            if chunk:
                print(chunk.decode("utf-8", "replace"), end="", flush=True)

        try:
            while True:
                drain()
                if not controller.alive(job):
                    drain()
                    break
                _time.sleep(2.0)
        except KeyboardInterrupt:
            print(
                "\n[detached. The worker is still running -- re-run this cell to follow it "
                "again, or set STOP = True in the Stop cell to halt it.]"
            )
            return controller.read_json(root / "status.json", {})

        status = controller.read_json(root / "status.json", {})
        print(f"\n[{mode} finished -- state: {status.get('state')}]")
        print(status.get("stage", ""))
        return status

    return (run,)


