    _labels = {'G0': 'Gemma 4 12B BF16', 'GF1': 'Gemma 4 12B D FP8', 'GF4': 'Gemma 4 12B D+A FP8'}
    for _item, _value in _progress.items():
        _pol, _k, _job = _item.split(":")
